(function(root){
'use strict';
const round=(n,d=1)=>Number(Number(n).toFixed(d));
function number(value,name,{min=0,max=1e12,allowZero=true}={}){const n=Number(value);if(!Number.isFinite(n)||n<min||n>max||(!allowZero&&n===0))throw Error(name+' must be a valid number');return n;}
function integer(value,name,{min=1,max=20}={}){const n=Number(value);if(!Number.isInteger(n)||n<min||n>max)throw Error(name+' must be an integer between '+min+' and '+max);return n;}
function normalize(input){
 const baseline=number(input.baselineWorkload,'Baseline workload',{min:0,max:1e9,allowZero:false}),target=number(input.targetWorkload,'Target workload',{min:0,max:1e9,allowZero:false}),capacity=number(input.capacityPerFte,'Capacity per FTE',{min:0,max:1e9,allowZero:false}),current=number(input.currentFte,'Current FTE',{min:0,max:1e6}),horizon=integer(input.horizonYears,'Horizon',{min:1,max:10}),attrition=number(input.attritionPercent??0,'Attrition',{min:0,max:50})/100,committed=number(input.committedHires??0,'Committed hires',{min:0,max:1e6}),internal=number(input.internalSupply??0,'Internal moves / reskilling',{min:0,max:1e6}),productivity=number(input.productivityGainPercent??0,'Productivity improvement',{min:-50,max:200})/100,cost=input.annualCostPerFte===''||input.annualCostPerFte===undefined||input.annualCostPerFte===null?null:number(input.annualCostPerFte,'Annual cost per FTE',{min:0,max:1e9});
 return {strategyObjective:String(input.strategyObjective||'').trim().slice(0,4000),role:String(input.role||'').trim().slice(0,300),department:String(input.department||'').trim().slice(0,300),jobFamily:String(input.jobFamily||'').trim().slice(0,300),workloadUnit:String(input.workloadUnit||'workload units').trim().slice(0,100)||'workload units',baselineWorkload:baseline,targetWorkload:target,capacityPerFte:capacity,currentFte:current,horizonYears:horizon,attritionRate:attrition,committedHires:committed,internalSupply:internal,productivityGain:productivity,annualCostPerFte:cost};
}
const scenarioDefs={
 low:{id:'low',labelAr:'طلب أقل',labelEn:'Lower demand',demandFactor:.9,productivityDelta:.05,attritionDelta:-.01},
 base:{id:'base',labelAr:'الأساس',labelEn:'Base',demandFactor:1,productivityDelta:0,attritionDelta:0},
 high:{id:'high',labelAr:'طلب مرتفع',labelEn:'Higher demand',demandFactor:1.1,productivityDelta:-.05,attritionDelta:.02}
};
function scenario(input,def){
 const target=Math.max(.0001,input.targetWorkload*def.demandFactor),growth=Math.pow(target/input.baselineWorkload,1/input.horizonYears)-1,productivity=Math.max(-.8,input.productivityGain+def.productivityDelta),attrition=Math.min(.8,Math.max(0,input.attritionRate+def.attritionDelta)),years=[];
 for(let year=1;year<=input.horizonYears;year++){
  const demand=input.baselineWorkload*Math.pow(1+growth,year),realizedProductivity=productivity*(year/input.horizonYears),capacity=input.capacityPerFte*(1+realizedProductivity),required=demand/capacity,retained=input.currentFte*Math.pow(1-attrition,year),newSupply=(input.committedHires+input.internalSupply)*(year/input.horizonYears),supply=retained+newSupply,gap=required-supply;
  years.push({year,demand:round(demand,1),capacityPerFte:round(capacity,1),requiredFte:round(required,1),recommendedHeadcount:Math.ceil(required),forecastSupplyFte:round(supply,1),gapFte:round(gap,1),gapHeadcount:gap>0?Math.ceil(gap):gap<0?-Math.ceil(Math.abs(gap)):0,annualGapCost:input.annualCostPerFte===null?null:round(Math.max(gap,0)*input.annualCostPerFte,0)});
 }
 const final=years.at(-1),action=final.gapFte>.5?'close-gap':final.gapFte<-.5?'redeploy':'balanced';
 return {id:def.id,labelAr:def.labelAr,labelEn:def.labelEn,assumptions:{targetWorkload:round(target,1),annualDemandGrowthPercent:round(growth*100,1),cumulativeProductivityPercent:round(productivity*100,1),annualAttritionPercent:round(attrition*100,1)},years,final,action};
}
function actions(plan){const base=plan.scenarios.base.final,items=[];if(base.gapFte>.5){items.push({type:'hire',quantity:Math.ceil(base.gapFte),textAr:'فجوة موجبة في السيناريو الأساسي: راجع التوظيف الخارجي بعد استنفاد النقل والتطوير الداخلي.',textEn:'Positive base-case gap: review external hiring after internal mobility and development options.'});items.push({type:'build',quantity:Math.ceil(base.gapFte),textAr:'حدد المهارات التي يمكن بناؤها داخليًا واربطها بخطة تطوير قبل إنشاء شواغر جديدة.',textEn:'Identify skills that can be built internally and link them to development before creating new vacancies.'});}else if(base.gapFte<-.5)items.push({type:'move',quantity:Math.ceil(Math.abs(base.gapFte)),textAr:'يوجد فائض قدرة محتمل؛ راجع إعادة التوزيع أو الاستنزاف الطبيعي بدل التوظيف.',textEn:'Potential capacity surplus: review redeployment or natural attrition instead of hiring.'});else items.push({type:'hold',quantity:0,textAr:'العرض والطلب قريبان من التوازن وفق الافتراضات الحالية؛ راقب مؤشرات الطلب والإنتاجية.',textEn:'Supply and demand are near balance under current assumptions; monitor demand and productivity indicators.'});return items;}
function plan(raw){const input=normalize(raw),scenarios=Object.fromEntries(Object.entries(scenarioDefs).map(([k,d])=>[k,scenario(input,d)])),result={schema:'miyar-manpower-plan/1.0',status:'scenario-estimate-not-approved',createdAt:new Date().toISOString(),input,scenarios};result.actions=actions(result);result.uncertainty={known:['Current FTE','Baseline workload','Target workload','Capacity per FTE','Planning horizon'],assumptionDriven:['Attrition','Committed hiring timing','Internal mobility timing','Productivity/automation realization','Demand scenario factors'],notice:'Scenario estimates are planning aids, not workforce commitments. Validate demand, capacity, attrition and budget with Finance and the business owner before approval.'};return result;}
const example={strategyObjective:'Deliver the Human Capital transformation portfolio on time while improving process efficiency and management reporting',role:'Human Capital Projects & Operations Manager',department:'Human Capital',jobFamily:'Human Capital',workloadUnit:'weighted HC initiatives / service units',baselineWorkload:100,targetWorkload:140,capacityPerFte:50,currentFte:2,horizonYears:3,attritionPercent:5,committedHires:0,internalSupply:0,productivityGainPercent:10,annualCostPerFte:300000};
root.MiyarManpower={plan,normalize,scenarioDefs,example};if(typeof module!=='undefined')module.exports=root.MiyarManpower;
})(typeof window!=='undefined'?window:globalThis);
